WITH valid AS (SELECT *, TRIM(channel) AS clean_channel, COALESCE(channel, 'OTHER') AS channel_filled FROM promotions WHERE starts_on > DATE '2023-04-08'), with_window AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM valid src JOIN promotions pr ON src.channel = pr.channel AND src.starts_on >= pr.starts_on AND src.starts_on <= DATE_ADD(pr.ends_on, 10)), scored AS (SELECT *, FIRST_VALUE(promo_id, TRUE) OVER (PARTITION BY YEAR(starts_on) ORDER BY promo_id ASC, id ASC, promo_id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_promo_id, AVG(discount_pct) OVER (PARTITION BY DATE_TRUNC('month', ends_on), promotion_promo_code ORDER BY promo_id ASC, id ASC, promo_id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY promo_id ASC, id ASC, promo_id ASC) AS seq_no FROM with_window), latest AS (SELECT id, promo_code, starts_on, clean_channel, channel_filled, promo_id, promotion_discount_pct, first_known_promo_id FROM scored QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY promo_id DESC, id ASC, promo_id ASC) = 1), scored_promotions AS (SELECT *, SUM(first_known_promo_id) OVER (ORDER BY promo_id ASC, id ASC, promo_id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_first_known_promo_id, NTILE(4) OVER (PARTITION BY promo_code ORDER BY first_known_promo_id ASC, id ASC, promo_id ASC) AS first_known_promo_id_bucket, NTILE(4) OVER (PARTITION BY promo_code ORDER BY promo_id DESC, id ASC, promo_id ASC) AS promo_id_bucket, FIRST_VALUE(promo_id) IGNORE NULLS OVER (PARTITION BY promo_code ORDER BY first_known_promo_id ASC, id ASC, promo_id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_promo_id_2 FROM latest), enriched AS (SELECT *, COUNT(first_known_promo_id) OVER (PARTITION BY promo_code) AS promo_code_count_first_known_promo_id, SUM(promotion_discount_pct) OVER (PARTITION BY promo_code ORDER BY first_known_promo_id_2 ASC, id ASC, promo_id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_promotion_discount_pct, FIRST_VALUE(promotion_discount_pct, TRUE) OVER (PARTITION BY promo_code ORDER BY first_known_promo_id_2 ASC, id ASC, promo_id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_promotion_discount_pct FROM scored_promotions) SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, APPROX_PERCENTILE(running_first_known_promo_id, ARRAY(0.25, 0.5, 0.75)) AS running_first_known_promo_id_quartiles, SUM(first_known_promo_id_bucket) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_total_first_known_promo_id_bucket, COUNT(*) AS num_rows, ROUND(SUM(promo_id) / NULLIF(COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END), 0), 2) AS promo_id_per_bundle, COUNT(DISTINCT id) AS distinct_ids FROM enriched GROUP BY activity_month ORDER BY welcome5_total_first_known_promo_id_bucket ASC
